cat > main.ts <<'EOF'
const MIN = -(1n << 63n);
const MAX = (1n << 63n) - 1n;

// Work on bytes: keys are equal when their bytes are equal, even if not valid UTF-8.
const latin1 = new TextDecoder("latin1");
const data = Deno.readFileSync(Deno.args[0]);

const lines: string[] = [];
{
  let start = 0;
  for (let i = 0; i <= data.length; i++) {
    if (i === data.length || data[i] === 0x0a) {
      if (i === data.length && start === i) break; // no trailing empty piece
      lines.push(latin1.decode(data.subarray(start, i)));
      start = i + 1;
    }
  }
}

// null marks an overflowed key
const totals = new Map<string, bigint | null>();
let i = 0;
for (; i < lines.length && lines[i] !== ""; i++) {
  const line = lines[i];
  const sp = line.indexOf(" ");
  if (sp < 0) continue;
  const key = line.slice(0, sp);
  let v: bigint;
  try {
    v = BigInt(line.slice(sp + 1).trim());
  } catch {
    continue;
  }
  const cur = totals.has(key) ? totals.get(key)! : 0n;
  if (cur === null) continue;
  const next = cur + v;
  totals.set(key, next < MIN || next > MAX ? null : next);
}

const out: number[] = [];
const enc = new TextEncoder();
const push = (s: string) => {
  for (let j = 0; j < s.length; j++) out.push(s.charCodeAt(j));
};
for (i++; i < lines.length; i++) {
  const key = lines[i];
  push(key);
  const t = totals.get(key);
  out.push(0x3d);
  if (t === undefined) push("absent");
  else if (t === null) push("overflow");
  else push(t.toString());
  out.push(0x0a);
}
void enc;
Deno.stdout.writeSync(new Uint8Array(out));
EOF
sed -i '' '/const enc = /d;/void enc;/d' main.ts
printf 'a 5\nb 9223372036854775807\nb 1\nключ -3\na 2\n\na\nb\nключ\nz\n' > /tmp/t.txt
deno check main.ts && deno run --allow-read main.ts /tmp/t.txt

